import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { usePermission } from '../contexts/PermissionContext';
import { PageHeader, Card, Button } from '../components/ui';

const EmployeeAssetsPage = () => {
  const [allAssets, setAllAssets] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [statusFilter, setStatusFilter] = useState('All');
  const { hasRole } = usePermission();

  const isEmployee = hasRole('Employee');
  const isSuperAdmin = hasRole('Super Admin');
  const isHRManager = hasRole('HR Manager');

  useEffect(() => {
    const fetchAndPrepareAssets = async () => {
      setIsLoading(true);
      try {
        const token = localStorage.getItem('authToken');
        let employeesData = [];

        if (isEmployee) {
          // Employee: Fetch only own data
          const response = await axios.get('http://127.0.0.1:8000/api/auth/me/', {
            headers: { Authorization: `Token ${token}` }
          });
          const userData = response.data;

          // Get employee details
          const empResponse = await axios.get(`http://127.0.0.1:8000/api/employees/${userData.employee_id}/`, {
            headers: { Authorization: `Token ${token}` }
          });
          employeesData = [empResponse.data];
        } else {
          // HR Manager & Super Admin: Fetch all employees
          const response = await axios.get('http://127.0.0.1:8000/api/employees/', {
            headers: { Authorization: `Token ${token}` }
          });
          employeesData = response.data.results || response.data || [];
        }

        // Generate multiple assets per employee
        const simulatedAssets = [];
        employeesData.forEach((employee) => {
          // Each employee gets 2-4 assets
          const assetTypes = [
            { type: 'Laptop', model: 'MacBook Pro 16"', status: 'Assigned' },
            { type: 'Monitor', model: 'Dell UltraSharp U27', status: 'Assigned' },
            { type: 'Phone', model: 'iPhone 14 Pro', status: 'Assigned' },
            { type: 'ID Card', model: 'Faculty Access Card', status: 'Assigned' },
          ];

          // For employees, show 2-3 assets; for admins, show varied assets
          const numAssets = isEmployee ? 3 : (employee.id % 3) + 2;

          for (let i = 0; i < numAssets; i++) {
            const asset = assetTypes[i % assetTypes.length];
            simulatedAssets.push({
              id: `ASSET-${employee.id}-${i}`,
              assetId: `${asset.type.substring(0, 2).toUpperCase()}-${1000 + employee.id * 10 + i}`,
              type: asset.type,
              model: asset.model,
              status: i === 0 ? 'Assigned' : (i === 1 ? 'Assigned' : 'In Repair'),
              custodian: `${employee.firstName} ${employee.lastName}`,
              department: employee.department,
              date: employee.joiningDate,
            });
          }
        });

        setAllAssets(simulatedAssets);
      } catch (error) {
        console.error("Error fetching data for assets:", error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchAndPrepareAssets();
  }, [isEmployee]);

  // Filtered assets are now derived from the status filter state
  const filteredAssets = allAssets.filter(asset => {
    if (statusFilter === 'All') {
      return true; // Show all assets
    }
    return asset.status === statusFilter; // Show only assets with the selected status
  });

  const getStatusBadge = (status) => {
    switch (status) {
      case 'Assigned': 
        return (
          <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200">
            Assigned
          </span>
        );
      case 'In Stock': 
        return (
          <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200">
            In Stock
          </span>
        );
      case 'In Repair': 
        return (
          <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200">
            In Repair
          </span>
        );
      case 'Retired': 
        return (
          <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200">
            Retired
          </span>
        );
      default: 
        return (
          <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-gray-100 text-gray-800 dark:bg-gray-900 dark:text-gray-200">
            {status}
          </span>
        );
    }
  };

  return (
    <div className="p-8">
      <div className="flex justify-between items-center mb-6">
          <div>
              <h1 className="text-3xl font-bold text-text-light dark:text-text-dark">
                {isEmployee ? 'My Assets' : 'Asset Management'}
              </h1>
              <p className="text-sm text-subtext-light">
                {isEmployee ? 'View your assigned assets and equipment.' : 'Filter and view all university assets.'}
              </p>
          </div>
          {!isEmployee && (
            <div className="w-full max-w-xs">
              <select 
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                className="w-full px-4 py-2 rounded-lg bg-card-light dark:bg-gray-800 border border-border-light dark:border-border-dark text-sm"
              >
                <option value="All">Filter by Status</option>
                <option value="Assigned">Assigned</option>
                <option value="In Stock">In Stock</option>
                <option value="In Repair">In Repair</option>
                <option value="Retired">Retired</option>
              </select>
            </div>
          )}
      </div>

      <div className="overflow-x-auto rounded-lg border border-border-light dark:border-border-dark bg-card-light dark:bg-card-dark">
        {isLoading ? (
            <div className="text-center py-10 text-subtext-light">Loading asset data...</div>
        ) : (
            <table className="w-full text-left text-sm">
                <thead className="bg-gray-50 text-xs uppercase">
                    <tr>
                        <th className="px-6 py-3">Asset ID</th>
                        <th className="px-6 py-3">Type</th>
                        <th className="px-6 py-3">Model/Name</th>
                        <th className="px-6 py-3">Status</th>
                        <th className="px-6 py-3">Current Custodian</th>
                        <th className="px-6 py-3">Department</th>
                        <th className="px-6 py-3">Purchase Date</th>
                    </tr>
                </thead>
                <tbody>
                    {filteredAssets.map(asset => (
                        <tr key={asset.id} className="border-b hover:bg-gray-50">
                            <td className="px-6 py-4 font-medium">{asset.id}</td>
                            <td className="px-6 py-4">{asset.type}</td>
                            <td className="px-6 py-4">{asset.model}</td>
                            <td className="px-6 py-4">{getStatusBadge(asset.status)}</td>
                            <td className="px-6 py-4 font-semibold text-text-light dark:text-white">{asset.custodian}</td>
                            <td className="px-6 py-4">{asset.department}</td>
                            <td className="px-6 py-4">{asset.date}</td>
                        </tr>
                    ))}
                </tbody>
            </table>
        )}
      </div>
    </div>
  );
};

export default EmployeeAssetsPage;
